@import 'tailwindcss';
@import 'tw-animate-css';
@import 'shadcn/tailwind.css';

@custom-variant dark (&:where(html:not([data-theme='light']), html:not([data-theme='light']) *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  /* Legacy UI alias: existing font-mono classes follow the interface font. */
  --font-mono: var(--font-geist-sans);
  --font-heading: var(--font-geist-sans);
  /* Explicit fixed-width font for branding and technical content. */
  --font-code: var(--font-geist-mono);
  /* FreeLingo semantic font-size tokens */
  --text-fl-hint: 10px;
  --text-fl-label: 11px;
  --text-fl-caption: 12px;
  /* FreeLingo semantic color tokens */
  --color-fl-bg: var(--fl-bg);
  --color-fl-bg-alt: var(--fl-bg-alt);
  --color-fl-surface: var(--fl-surface);
  --color-fl-surface-2: var(--fl-surface-2);
  --color-fl-border: var(--fl-border);
  --color-fl-border-2: var(--fl-border-2);
  --color-fl-muted: var(--fl-muted-1);
  --color-fl-muted-4: var(--fl-muted-4);
  --color-fl-muted-3: var(--fl-muted-3);
  --color-fl-muted-2: var(--fl-muted-2);
  --color-fl-muted-1: var(--fl-muted-1);
  --color-fl-muted-0: var(--fl-muted-0);
  --color-fl-fg-2: var(--fl-fg-2);
  --color-fl-fg: var(--fl-fg);
  --color-fl-fg-bright: var(--fl-fg-bright);
  /* FreeLingo error/danger tokens */
  --color-fl-error: var(--fl-error);
  --color-fl-error-fg: var(--fl-error-fg);
  --color-fl-error-dim: var(--fl-error-dim);
  --color-fl-error-hover: var(--fl-error-hover);
  --color-fl-success: var(--fl-success);
  --color-fl-warning: var(--fl-warning);
  /* FreeLingo accent tokens */
  --color-fl-accent: var(--fl-accent);
  --color-fl-accent-fg: var(--fl-accent-fg);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --radius-sm: 0px;
  --radius-md: 0px;
  --radius-lg: 0px;
  --radius-xl: 0px;
  /* Avatar halo animations */
  --animate-halo-idle: halo-idle 3s ease-in-out infinite;
  --animate-halo-speaking: halo-speaking 0.65s ease-in-out infinite;
}

:root {
  /* FreeLingo semantic tokens — dark (default) */
  --fl-bg: #0c1316;
  --fl-bg-alt: #0d0d0d;
  --fl-surface: #131d22;
  --fl-surface-2: #1a1a1a;
  --fl-border: #29383f;
  --fl-border-2: #444444;
  --fl-muted-4: #666666;
  --fl-muted-3: #777777;
  --fl-muted-2: #888888;
  --fl-muted-1: #999999;
  --fl-muted-0: #aaaaaa;
  --fl-fg-2: #e0e0e0;
  --fl-fg: var(--fl-fg-2);
  --fl-fg-bright: #ffffff;
  --fl-error: #ff3b3b;
  --fl-error-fg: #ff6b6b;
  --fl-error-dim: #cc6666;
  --fl-error-hover: #ff5555;
  --fl-success: #4ade80;
  --fl-warning: #fbbf24;
  --fl-accent: #75b7c5;
  --fl-accent-fg: #0a0a0a;
  /* shadcn tokens */
  --background: var(--fl-bg);
  --foreground: var(--fl-fg-2);
  --card: var(--fl-surface);
  --card-foreground: var(--fl-fg-2);
  --popover: var(--fl-surface);
  --popover-foreground: var(--fl-fg-2);
  --primary: var(--fl-fg-2);
  --primary-foreground: var(--fl-bg);
  --secondary: #1a1a1a;
  --secondary-foreground: var(--fl-fg-2);
  --muted: #1a1a1a;
  --muted-foreground: #666666;
  --accent: #1a1a1a;
  --accent-foreground: var(--fl-fg-2);
  --destructive: #ff3b3b;
  --border: var(--fl-border);
  --input: #1a1a1a;
  --ring: #444444;
  --radius: 0px;
  --sidebar: var(--fl-bg);
  --sidebar-foreground: var(--fl-fg-2);
  --sidebar-primary: var(--fl-fg-2);
  --sidebar-primary-foreground: var(--fl-bg);
  --sidebar-accent: #1a1a1a;
  --sidebar-accent-foreground: var(--fl-fg-2);
  --sidebar-border: var(--fl-border);
  --sidebar-ring: #444444;
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }

  body {
    @apply bg-background text-foreground font-sans;
  }

  html {
    @apply scroll-smooth font-sans;
  }

  code,
  pre,
  kbd,
  samp {
    @apply font-code;
  }

  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    letter-spacing: -0.02em;
  }

  :lang(ar) h1,
  :lang(ar) h2,
  :lang(ar) h3,
  :lang(ar) h4,
  :lang(ar) h5,
  :lang(ar) h6 {
    letter-spacing: normal;
  }
}

@utility font-target-latin {
  font-family:
    var(--font-geist-sans),
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    'Segoe UI',
    sans-serif;
}

@utility font-target-ja {
  font-family:
    var(--font-noto-ja), 'Hiragino Sans', 'Yu Gothic', Meiryo, system-ui,
    sans-serif;
}

@utility font-target-ko {
  font-family:
    var(--font-noto-ko), 'Apple SD Gothic Neo', 'Malgun Gothic', system-ui,
    sans-serif;
}

@utility font-target-zh {
  font-family:
    var(--font-noto-zh), 'PingFang SC', 'Microsoft YaHei', 'Noto Sans CJK SC',
    system-ui, sans-serif;
}

/* Scrollbars belong to the authenticated Duolingo shell, not the public landing. */
.juba-duo-shell {
  scrollbar-color: var(--duo-line) var(--duo-bg);
  scrollbar-width: thin;
}

.juba-duo-shell *::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

.juba-duo-shell *::-webkit-scrollbar-track {
  background: var(--duo-bg);
}

.juba-duo-shell *::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: var(--duo-line);
}

.juba-duo-shell *::-webkit-scrollbar-thumb:hover {
  background: color-mix(in srgb, var(--duo-muted) 55%, var(--duo-line));
}

/* ── Light theme ── */
html[data-theme='light'] {
  --fl-bg: #f2f6f7;
  --fl-bg-alt: #f0f0f0;
  --fl-surface: #fbfcfc;
  --fl-surface-2: #eeeeee;
  --fl-border: #d7e1e5;
  --fl-border-2: #aaaaaa;
  --fl-muted-4: #999999;
  --fl-muted-3: #888888;
  --fl-muted-2: #777777;
  --fl-muted-1: #666666;
  --fl-muted-0: #555555;
  --fl-fg-2: #1a1a1a;
  --fl-fg: #0a0a0a;
  --fl-fg-bright: #000000;
  --fl-error: #e03030;
  --fl-error-fg: #cc3333;
  --fl-error-dim: #994444;
  --fl-error-hover: #c02020;
  --fl-success: #15803d;
  --fl-warning: #92400e;
  --fl-accent: #286779;
  --fl-accent-fg: #ffffff;
  /* shadcn token overrides (light) */
  --background: var(--fl-bg);
  --foreground: #0a0a0a;
  --card: var(--fl-surface);
  --card-foreground: #0a0a0a;
  --popover: var(--fl-surface);
  --popover-foreground: #0a0a0a;
  --primary: #0a0a0a;
  --primary-foreground: var(--fl-bg);
  --secondary: #eeeeee;
  --secondary-foreground: #0a0a0a;
  --muted: #eeeeee;
  --muted-foreground: #666666;
  --accent: #eeeeee;
  --accent-foreground: #0a0a0a;
  --border: var(--fl-border);
  --input: #eeeeee;
  --ring: #aaaaaa;
  --sidebar: var(--fl-bg);
  --sidebar-foreground: #0a0a0a;
  --sidebar-primary: #0a0a0a;
  --sidebar-primary-foreground: var(--fl-bg);
  --sidebar-accent: #eeeeee;
  --sidebar-accent-foreground: #0a0a0a;
  --sidebar-border: var(--fl-border);
  --sidebar-ring: #aaaaaa;
}

/* ── Avatar halo keyframes ── */
@keyframes halo-idle {
  0%,
  100% {
    opacity: 0.15;
    transform: scale(1);
  }

  50% {
    opacity: 0.32;
    transform: scale(1.07);
  }
}

@keyframes halo-speaking {
  0%,
  100% {
    opacity: 0.55;
    transform: scale(1);
  }

  40% {
    opacity: 0.92;
    transform: scale(1.14);
  }
}

.juba-duo-shell .word-selectable::selection,
.juba-duo-shell .word-selectable *::selection {
  background: color-mix(in srgb, var(--duo-green) 28%, transparent);
}

.juba-busuu-page .word-selectable::selection,
.juba-busuu-page .word-selectable *::selection {
  background: color-mix(in srgb, var(--busuu-green) 24%, transparent);
}

.juba-busuu-page {
  scrollbar-color: var(--busuu-line) var(--busuu-cream);
}

.juba-busuu-page::-webkit-scrollbar-track {
  background: var(--busuu-cream);
}

.juba-busuu-page::-webkit-scrollbar-thumb {
  background: var(--busuu-line);
}

.juba-busuu-page::-webkit-scrollbar-thumb:hover {
  background: var(--busuu-muted);
}

/* ── Scroll-reveal animation ── */
.juba-busuu-page .reveal {
  opacity: 0;
  transform: translateY(24px);
  transition:
    opacity 0.6s ease-out,
    transform 0.6s ease-out;
}

.juba-busuu-page .reveal-visible {
  opacity: 1;
  transform: translateY(0);
}

/* ── Language bubbles floating animation ── */
@keyframes float {
  0%,
  100% {
    transform: translateY(0px);
  }
  50% {
    transform: translateY(-6px);
  }
}

@keyframes bubble-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.9);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.juba-busuu-page .animate-float {
  animation: float 3s ease-in-out infinite;
}

.juba-busuu-page .animate-bubble-in {
  animation: bubble-in 0.4s ease-out forwards;
  opacity: 0;
}


/* ==========================================================================
   JUBA LISAN design systems
   theme/ is reference-only. Runtime styling is reimplemented here.
   ========================================================================== */

/* ── Busuu-derived public landing ───────────────────────────────────────── */
.juba-busuu-page {
  --busuu-ink: #17211b;
  --busuu-muted: #53615a;
  --busuu-green: #00a86b;
  --busuu-green-dark: #008957;
  --busuu-mint: #e8f8f0;
  --busuu-cream: #fbfaf6;
  --busuu-card: #ffffff;
  --busuu-line: #dce5df;
  background: var(--busuu-cream);
  color: var(--busuu-ink);
  overflow-x: clip;
}

.juba-busuu-page * { box-sizing: border-box; }
.juba-busuu-page a { color: inherit; }
.juba-busuu-page h1,
.juba-busuu-page h2,
.juba-busuu-page h3,
.juba-busuu-page h4 { color: var(--busuu-ink); }

.juba-busuu-nav {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(251,250,246,.96);
  border-bottom: 1px solid var(--busuu-line);
  backdrop-filter: blur(14px);
}
.juba-busuu-nav-inner {
  width: min(1240px, calc(100% - 48px));
  min-height: 76px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 28px;
}
.juba-busuu-brand { display:flex; align-items:center; flex:0 0 auto; }
.juba-busuu-brand img { width: 150px; height:auto; display:block; }
.juba-busuu-nav-links {
  display:flex; align-items:center; justify-content:center; gap:30px;
  flex:1; font-size:14px; font-weight:650;
}
.juba-busuu-nav-links a,
.juba-busuu-login {
  text-decoration:none; color:var(--busuu-ink); transition:color .18s ease;
}
.juba-busuu-nav-links a:hover,
.juba-busuu-login:hover { color:var(--busuu-green-dark); }
.juba-busuu-nav-actions { display:flex; align-items:center; gap:12px; }
.juba-busuu-login { padding:12px 10px; font-size:14px; font-weight:650; }
.juba-busuu-nav-cta,
.juba-busuu-mobile-cta {
  display:inline-flex; align-items:center; justify-content:center;
  min-height:44px; padding:0 20px; border-radius:999px;
  background:var(--busuu-green); color:white !important;
  text-decoration:none; font-size:14px; font-weight:750;
  box-shadow:0 3px 0 var(--busuu-green-dark);
  transition:transform .15s ease, background .15s ease, box-shadow .15s ease;
}
.juba-busuu-nav-cta:hover,
.juba-busuu-mobile-cta:hover { background:var(--busuu-green-dark); transform:translateY(1px); box-shadow:0 2px 0 #006d47; }
.juba-busuu-locale-menu { position:relative; }
.juba-busuu-locale {
  list-style:none; cursor:pointer; display:flex; align-items:center; gap:5px;
  padding:10px 8px; border:0; background:transparent; font-size:12px; font-weight:800;
}
.juba-busuu-locale::-webkit-details-marker { display:none; }
.juba-busuu-locale svg { width:15px; height:15px; }
.juba-busuu-locale-options {
  position:absolute; top:calc(100% + 10px); inset-inline-end:0; min-width:170px;
  padding:8px; border:1px solid var(--busuu-line); border-radius:14px;
  background:var(--busuu-card); box-shadow:0 16px 45px color-mix(in srgb,var(--busuu-ink) 12%,transparent);
}
.juba-busuu-locale-options a {
  display:block; padding:9px 11px; border-radius:9px; text-decoration:none; font-size:13px;
}
.juba-busuu-locale-options a:hover { background:var(--busuu-mint); color:var(--busuu-green-dark); }
.juba-busuu-menu { display:none; border:0; background:transparent; padding:8px; }
.juba-busuu-menu svg { width:24px; height:24px; }

.juba-busuu-language-list {
  list-style:none; margin:0 auto; padding:0; width:min(980px,100%);
  display:flex; flex-wrap:wrap; align-items:center; justify-content:center;
  gap:14px 18px; min-height:170px;
}
.juba-busuu-language-item {
  display:flex; flex-direction:column; align-items:center; gap:6px;
  min-width:76px; color:var(--busuu-muted); font-size:12px; font-weight:700;
}
.juba-busuu-language-item img {
  width:54px; height:40px; object-fit:cover; border-radius:8px;
  box-shadow:0 4px 12px rgba(25,40,32,.10);
}
.juba-busuu-page section:not(:first-of-type) {
  position:relative;
}
.juba-busuu-page .border-fl-border,
.juba-busuu-page .border-t { border-color:var(--busuu-line) !important; }
.juba-busuu-page .bg-fl-surface { background:var(--busuu-card) !important; }
.juba-busuu-page .text-fl-fg,
.juba-busuu-page .text-fl-fg-2 { color:var(--busuu-ink) !important; }
.juba-busuu-page .text-fl-muted-1,
.juba-busuu-page .text-fl-muted-2,
.juba-busuu-page .text-fl-muted-3,
.juba-busuu-page .text-fl-muted-4 { color:var(--busuu-muted) !important; }
.juba-busuu-page .bg-fl-accent { background:var(--busuu-green) !important; }
.juba-busuu-page .text-fl-accent { color:var(--busuu-green-dark) !important; }

.juba-busuu-page .juba-busuu-footer {
  background:#15211b; color:#dce9e1; border-color:#2b3b32 !important;
}
.juba-busuu-page .juba-busuu-footer-brand { color:#fff; font-weight:800; }
.juba-busuu-page .juba-busuu-footer .text-fl-muted-3,
.juba-busuu-page .juba-busuu-footer .text-fl-muted-4,
.juba-busuu-page .juba-busuu-footer .text-fl-muted-2 { color:#b4c6bb !important; }
.juba-busuu-page .juba-busuu-footer h4 { color:#fff !important; }

.juba-busuu-mobile-menu {
  display:none; border-top:1px solid var(--busuu-line); background:var(--busuu-cream);
  padding:18px 24px 26px; max-height:calc(100vh - 76px); overflow:auto;
}
.juba-busuu-mobile-menu[hidden] { display:none; }
.juba-busuu-mobile-menu nav { display:flex; flex-direction:column; gap:2px; }
.juba-busuu-mobile-menu nav a { padding:13px 0; text-decoration:none; font-weight:650; }
.juba-busuu-mobile-actions { display:flex; flex-direction:column; gap:10px; padding-top:14px; }
.juba-busuu-mobile-locales {
  display:grid !important; grid-template-columns:repeat(2,minmax(0,1fr)); gap:4px 14px !important;
  padding-top:12px; border-top:1px solid var(--busuu-line);
}
.juba-busuu-mobile-locales a { font-size:13px; }

@media (max-width: 1000px) {
  .juba-busuu-nav-inner { width:min(100% - 32px,1240px); min-height:68px; }
  .juba-busuu-nav-links, .juba-busuu-nav-actions { display:none; }
  .juba-busuu-menu { display:block; margin-inline-start:auto; }
  .juba-busuu-mobile-menu { display:block; }
  .juba-busuu-page > section:first-of-type { min-height:610px; }
  .juba-busuu-page > section:first-of-type h1 { font-size:clamp(38px,9vw,58px); }
}
@media (max-width: 640px) {
  .juba-busuu-nav-inner { width:calc(100% - 24px); }
  .juba-busuu-brand img { width:128px; }
  .juba-busuu-page > section:first-of-type { min-height:590px; padding-inline:18px !important; }
  .juba-busuu-page > section:first-of-type h1 { font-size:40px; }
  .juba-busuu-language-list { gap:10px 8px; }
  .juba-busuu-language-item { min-width:64px; font-size:10px; }
  .juba-busuu-language-item img { width:44px; height:32px; }
}

/* ── Landing section refinement ─────────────────────────────────────────── */
.juba-busuu-hero { isolation:isolate; overflow:hidden; }
.juba-busuu-hero > div:first-of-type { position:relative; z-index:1; }
.juba-busuu-demo, .juba-busuu-section, .juba-busuu-pricing { width:100%; }
.juba-busuu-demo { background:#fff; padding-top:8px; }
.juba-busuu-demo-card { border-radius:24px !important; box-shadow:0 14px 40px rgba(23,33,27,.08); overflow:hidden; }
.juba-busuu-demo-card > div:first-child { background:#f4fbf7; }
.juba-busuu-feature-card { border-radius:20px !important; padding:28px !important; box-shadow:0 8px 28px rgba(23,33,27,.06); transition:transform .18s ease, box-shadow .18s ease; }
.juba-busuu-feature-card:hover { transform:translateY(-3px); box-shadow:0 14px 34px rgba(23,33,27,.09); }
.juba-busuu-pricing { padding-block:8px 20px; }
.juba-busuu-open-source { border-radius:20px !important; box-shadow:0 8px 28px rgba(23,33,27,.06); }
.juba-busuu-section h2 { letter-spacing:-.035em; }
.juba-busuu-section a:not(.juba-busuu-nav-cta) { text-decoration-thickness:1px; text-underline-offset:3px; }
/* Direction is inherited from the landing root; use logical positioning for both locales. */
.juba-busuu-page .juba-busuu-footer { direction:inherit; }
@media (max-width:640px) { .juba-busuu-demo-card { border-radius:18px !important; } .juba-busuu-feature-card { padding:22px !important; } }
@media (prefers-reduced-motion:reduce) {
  .juba-busuu-page *, .juba-busuu-page *::before, .juba-busuu-page *::after { scroll-behavior:auto !important; animation-duration:.01ms !important; transition-duration:.01ms !important; }
}

/* ── Busuu landing: lesson demo surface and hierarchy ──────────────────── */
.juba-busuu-page .juba-busuu-demo-section {
  padding-top: clamp(36px, 5vw, 68px);
}
.juba-busuu-page .juba-busuu-demo-card {
  border: 1px solid var(--busuu-line);
  border-radius: 24px;
  background: var(--busuu-card);
  color: var(--busuu-ink);
  box-shadow: 0 16px 44px color-mix(in srgb, var(--busuu-ink) 8%, transparent);
  overflow: hidden;
}
.juba-busuu-page .juba-busuu-demo-card-header {
  border-color: var(--busuu-line);
  background: linear-gradient(115deg, var(--busuu-mint), #fff 78%);
}
.juba-busuu-page .juba-busuu-demo-title {
  color: var(--busuu-ink);
  font-family: var(--font-geist-sans), sans-serif;
  letter-spacing: -.02em;
}
.juba-busuu-page .juba-busuu-demo-subtitle,
.juba-busuu-page .juba-busuu-demo-label {
  color: var(--busuu-muted);
  font-family: var(--font-geist-sans), sans-serif;
