/* ── Duolingo-derived application shell ─────────────────────────────────── */
.juba-duo-shell {
  /* Busuu-inspired palette applied to the authenticated JUBA LISAN interface. */
  --duo-green:#00a86b;
  --duo-green-dark:#008957;
  --duo-blue:#168fcb;
  --duo-blue-dark:#1176a8;
  --duo-purple:#8b78c7;
  --duo-yellow:#d79a18;
  --duo-red:#d94f55;
  --duo-ink:#17211b;
  --duo-muted:#53615a;
  --duo-bg:#fbfaf6;
  --duo-card:#ffffff;
  --duo-line:#dce5df;
  min-height:100dvh;
  background:var(--duo-bg);
  color:var(--duo-ink);
  display:flex;
  font-family:var(--font-geist-sans), system-ui, sans-serif;
}
.juba-duo-shell .bg-fl-bg { background:var(--duo-bg) !important; color:var(--duo-ink) !important; }
.juba-duo-shell .bg-fl-surface,
.juba-duo-shell .bg-fl-surface-2 { background:var(--duo-card) !important; }
.juba-duo-shell .text-fl-fg,
.juba-duo-shell .text-fl-fg-2 { color:var(--duo-ink) !important; }
.juba-duo-shell .text-fl-muted-1,
.juba-duo-shell .text-fl-muted-2,
.juba-duo-shell .text-fl-muted-3,
.juba-duo-shell .text-fl-muted-4 { color:var(--duo-muted) !important; }
.juba-duo-shell .border-fl-border,
.juba-duo-shell .border-fl-border-2 { border-color:var(--duo-line) !important; }

.juba-duo-sidebar {
  position:fixed; inset-block:0; inset-inline-start:0; width:250px; z-index:40;
  background:var(--duo-card); border-inline-end:2px solid var(--duo-line);
  display:flex; flex-direction:column; min-height:100dvh;
}
.juba-duo-logo-mark {
  display:grid; place-items:center; width:38px; height:38px; border-radius:12px;
  background:var(--duo-green); color:#fff; font-weight:900; letter-spacing:-.04em;
  box-shadow:inset 0 -3px 0 var(--duo-green-dark);
}
.juba-duo-language { padding:10px 16px; border-bottom:1px solid var(--duo-line); }
.juba-duo-nav {
  flex:1;
  min-height:0;
  overflow:auto;
  overscroll-behavior:contain;
  padding:12px 10px;
  scrollbar-width:thin;
}
.juba-duo-nav-link:focus-visible,
.juba-duo-resource-toggle:focus-visible,
.juba-duo-user-action:focus-visible,
.juba-duo-mobile-trigger:focus-visible,
.juba-duo-language :focus-visible,
.juba-duo-mobile-menu > .border-b :focus-visible {
  outline:3px solid color-mix(in srgb,var(--duo-blue) 55%,transparent);
  outline-offset:2px;
  position:relative;
  z-index:1;
}
.juba-duo-nav-link {
  display:flex; align-items:center; gap:12px; width:100%; min-height:44px;
  padding:9px 12px; margin:2px 0; border-radius:12px; border:0;
  text-decoration:none; color:var(--duo-muted); font-size:14px; font-weight:700;
  transition:background .15s ease, color .15s ease, transform .1s ease;
}
.juba-duo-nav-link:hover { background:color-mix(in srgb,var(--duo-green) 8%,transparent); color:var(--duo-ink); }
.juba-duo-nav-link.is-active {
  background:color-mix(in srgb,var(--duo-green) 14%,transparent); color:var(--duo-green-dark); box-shadow:inset 4px 0 0 var(--duo-green);
}
.juba-duo-shell[dir="rtl"] .juba-duo-nav-link.is-active { box-shadow:inset -4px 0 0 var(--duo-green); }

.juba-duo-shell[dir="rtl"] .juba-duo-node-row.is-offset { transform:translateX(-58px); }
.juba-duo-resource-toggle {
  display:flex; align-items:center; justify-content:space-between; width:100%;
  border:0; background:transparent; padding:11px 12px; color:var(--duo-muted);
  font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:.08em;
}
.juba-duo-nav-link-sub { padding-inline-start:30px; min-height:40px; }
.juba-duo-nav-divider { margin-top:10px; padding-top:10px; border-top:1px solid var(--duo-line); }
.juba-duo-user { margin-top:auto; padding:14px; border-top:1px solid var(--duo-line); background:var(--duo-card); }
.juba-duo-version { color:var(--duo-muted); font-size:10px; margin:0 0 8px; }
.juba-duo-user-action {
  display:block; width:100%; border:0; background:transparent; color:var(--duo-muted);
  text-align:start; padding:7px 2px; font-size:12px; font-weight:700;
}
.juba-duo-user-action:hover { color:var(--duo-ink); }
.juba-duo-mobile-menu {
  position:fixed;
  top:calc(66px + env(safe-area-inset-top, 0px));
  inset-inline:0;
  z-index:49;
  background:var(--duo-card);
  border-bottom:2px solid var(--duo-line);
  box-shadow:0 12px 30px color-mix(in srgb,var(--duo-ink) 10%,transparent);
  max-height:calc(100dvh - 66px - env(safe-area-inset-top, 0px));
  overflow:auto;
}
.juba-duo-shell .juba-duo-mobile-menu {
  box-sizing:border-box;
  padding-bottom:env(safe-area-inset-bottom,0px);
  overscroll-behavior-y:contain;
  scrollbar-gutter:stable;
}
.juba-duo-mobile-menu a:focus-visible,
.juba-duo-mobile-menu button:focus-visible {
  outline:3px solid color-mix(in srgb,var(--duo-blue) 45%,transparent);
  outline-offset:-3px;
  position:relative;
  z-index:1;
}
.juba-duo-mobile-bar { background:var(--duo-card) !important; border-color:var(--duo-line) !important; color:var(--duo-ink) !important; }
.juba-duo-mobile-bar .border-fl-border { border-color:var(--duo-line) !important; }
.juba-duo-mobile-bar .bg-fl-bg { background:var(--duo-card) !important; }
.juba-duo-mobile-brand { font-weight:900; color:var(--duo-ink); letter-spacing:.06em; }
.juba-duo-mobile-trigger { border:0; background:var(--duo-card); color:var(--duo-ink); width:40px; height:40px; border-radius:10px; }
.juba-duo-mobile-trigger:hover { background:color-mix(in srgb,var(--duo-ink) 5%,transparent); }
.juba-duo-home {
  width:100%; margin:0; min-height:100dvh;
  padding:34px clamp(22px,4vw,64px) 60px;
}
.juba-duo-shell[dir="rtl"] .juba-duo-main { margin-inline-start:250px; margin-inline-end:0; }
.juba-duo-shell[dir="rtl"] .juba-duo-home { margin:0; }
.juba-duo-welcome {
  max-width:1120px; margin:0 auto 24px; display:flex; align-items:flex-end;
  justify-content:space-between; gap:24px;
}
.juba-duo-eyebrow { display:block; color:var(--duo-muted); font-size:12px; font-weight:800; text-transform:uppercase; letter-spacing:.09em; margin-bottom:7px; }
.juba-duo-welcome h1 { margin:0; color:var(--duo-ink); font-size:clamp(28px,3vw,42px); font-weight:900; letter-spacing:-.04em; }
.juba-duo-welcome p { margin:7px 0 0; color:var(--duo-muted); font-size:15px; }
.juba-duo-top-stats { display:flex; gap:12px; }
.juba-duo-top-stats > div {
  min-width:100px; display:grid; grid-template-columns:auto 1fr; grid-template-rows:auto auto;
  column-gap:8px; padding:11px 14px; background:var(--duo-card); border:2px solid var(--duo-line); border-radius:14px;
}
.juba-duo-top-stats svg { grid-row:1 / span 2; align-self:center; color:var(--duo-yellow); }
.juba-duo-top-stats strong { font-size:18px; line-height:1; color:var(--duo-ink); }
.juba-duo-top-stats span { font-size:10px; color:var(--duo-muted); font-weight:800; text-transform:uppercase; }
.juba-duo-alert { max-width:1120px; margin:0 auto 18px; padding:12px 16px; background:color-mix(in srgb,var(--duo-red) 8%,transparent); border:2px solid color-mix(in srgb,var(--duo-red) 35%,transparent); border-radius:12px; color:var(--duo-red); display:flex; justify-content:space-between; gap:14px; align-items:center; }
.juba-duo-alert button { border:0; background:var(--duo-red); color:#fff; padding:8px 14px; border-radius:10px; font-weight:800; }
.juba-duo-grid { max-width:1120px; margin:0 auto; display:grid; grid-template-columns:minmax(0,1.65fr) minmax(280px,.8fr); gap:22px; }
.juba-duo-course,.juba-duo-side { min-width:0; }
.juba-duo-unit {
  background:var(--duo-card); border:2px solid var(--duo-line); border-radius:18px; padding:22px;
  box-shadow:0 2px 0 color-mix(in srgb,var(--duo-ink) 3%,transparent);
}
.juba-duo-unit-head { display:flex; align-items:center; justify-content:space-between; gap:16px; }
.juba-duo-unit-kicker { color:var(--duo-green-dark); font-size:11px; font-weight:900; text-transform:uppercase; letter-spacing:.08em; }
.juba-duo-unit h2 { margin:5px 0 0; font-size:22px; color:var(--duo-ink); font-weight:900; }
.juba-duo-guide,.juba-duo-card-link { color:var(--duo-blue-dark); font-size:13px; font-weight:800; text-decoration:none; }
.juba-duo-progress { height:14px; margin-top:20px; overflow:hidden; border-radius:999px; background:var(--duo-line); }
.juba-duo-progress span,.juba-duo-meter span { display:block; height:100%; border-radius:inherit; background:var(--duo-green); }
.juba-duo-progress-meta { display:flex; justify-content:space-between; margin-top:7px; color:var(--duo-muted); font-size:11px; font-weight:800; }
.juba-duo-path { position:relative; padding:24px 8px 8px; }
.juba-duo-node-row { position:relative; display:flex; align-items:center; gap:18px; max-width:620px; margin:0 auto 16px; }
.juba-duo-node-row.is-offset { transform:translateX(58px); }
.juba-duo-node {
  position:relative; z-index:1; display:grid; place-items:center; width:70px; height:70px; flex:0 0 70px;
  border-radius:50%; background:var(--duo-card); border:4px solid var(--duo-line); color:var(--duo-muted);
  box-shadow:0 5px 0 var(--duo-line);
}
.juba-duo-node.is-done { background:var(--duo-green); border-color:var(--duo-green-dark); color:#fff; box-shadow:0 5px 0 var(--duo-green-dark); }
.juba-duo-node.is-current { background:var(--duo-blue); border-color:var(--duo-blue-dark); color:#fff; box-shadow:0 5px 0 var(--duo-blue-dark); }
.juba-duo-node-copy { display:flex; flex-direction:column; gap:4px; min-width:0; }
.juba-duo-node-copy strong { font-size:15px; font-weight:900; color:var(--duo-ink); }
.juba-duo-node-copy span { font-size:12px; color:var(--duo-muted); }
.juba-duo-cta {
  width:max-content; display:inline-flex; align-items:center; justify-content:center; min-height:40px; padding:0 17px;
  margin-top:5px; border-radius:12px; background:var(--duo-green); color:#fff !important; text-decoration:none; font-size:13px; font-weight:900;
  box-shadow:0 3px 0 var(--duo-green-dark);
}
.juba-duo-cta:hover { background:var(--duo-green-dark); transform:translateY(1px); }
.juba-duo-complete { display:inline-flex; align-items:center; gap:5px; color:var(--duo-green-dark) !important; font-weight:800; }
.juba-duo-empty { display:flex; flex-direction:column; align-items:center; gap:10px; padding:42px 20px; text-align:center; color:var(--duo-muted); }
.juba-duo-empty h3 { margin:0; color:var(--duo-ink); }
.juba-duo-card { background:var(--duo-card); border:2px solid var(--duo-line); border-radius:16px; padding:18px; margin-bottom:14px; box-shadow:0 2px 0 color-mix(in srgb,var(--duo-ink) 3%,transparent); }
.juba-duo-streak-card { display:flex; align-items:center; gap:14px; }
.juba-duo-card-icon { display:grid; place-items:center; width:48px; height:48px; border-radius:14px; background:color-mix(in srgb,var(--duo-yellow) 18%,transparent); color:var(--duo-yellow); }
.juba-duo-streak-card strong { display:block; font-size:28px; line-height:1; color:var(--duo-ink); }
.juba-duo-streak-card span,.juba-duo-streak-card small { display:block; color:var(--duo-muted); font-size:11px; font-weight:800; text-transform:uppercase; }
.juba-duo-card-head { display:flex; align-items:center; justify-content:space-between; gap:12px; }
.juba-duo-card-head h3 { margin:0; font-size:14px; color:var(--duo-ink); font-weight:900; }
.juba-duo-card-head > span { color:var(--duo-green-dark); font-size:13px; font-weight:900; }
.juba-duo-meter { height:10px; overflow:hidden; border-radius:999px; background:var(--duo-line); margin:13px 0 8px; }
.juba-duo-card p { margin:0; color:var(--duo-muted); font-size:12px; line-height:1.5; }
.juba-duo-mini-bars { height:90px; display:flex; align-items:flex-end; gap:7px; margin-top:12px; }
.juba-duo-mini-bars span { flex:1; min-height:8px; border-radius:7px 7px 2px 2px; background:var(--duo-blue); }
.juba-duo-mini-bars i { color:var(--duo-muted); font-size:12px; }
.juba-duo-links { display:grid; grid-template-columns:1fr 1fr; gap:8px; }
.juba-duo-links a { display:flex; align-items:center; gap:8px; padding:12px; border-radius:12px; background:var(--duo-card); border:2px solid var(--duo-line); color:var(--duo-muted); text-decoration:none; font-size:12px; font-weight:800; }
.juba-duo-links a:hover { border-color:var(--duo-green); background:color-mix(in srgb,var(--duo-green) 8%,transparent); }
.juba-duo-premium {
  max-width:1120px; margin:22px auto 0; padding:16px 18px; display:flex; align-items:center; gap:14px;
  background:color-mix(in srgb,var(--duo-yellow) 16%,var(--duo-card));
  border:2px solid color-mix(in srgb,var(--duo-yellow) 45%,var(--duo-line));
  border-radius:16px; color:var(--duo-ink);
}
.juba-duo-premium > div { flex:1; display:flex; flex-direction:column; gap:3px; }
.juba-duo-premium strong { color:var(--duo-ink); font-size:14px; }
.juba-duo-premium span { font-size:12px; color:var(--duo-muted); }
.juba-duo-premium button { border:0; border-radius:10px; background:var(--duo-green); color:#fff; padding:9px 14px; font-weight:900; }
.juba-duo-shell input,.juba-duo-shell select,.juba-duo-shell textarea {
  border:2px solid var(--duo-line); background:var(--duo-card); color:var(--duo-ink); border-radius:12px;
}
.juba-duo-shell button { font-family:inherit; }
.juba-duo-shell button:not(.juba-duo-user-action):not(.juba-duo-mobile-trigger) { border-radius:12px; }
.juba-duo-shell .bg-fl-accent { background:var(--duo-green) !important; color:#fff !important; }
.juba-duo-shell .text-fl-accent { color:var(--duo-green-dark) !important; }

@media (max-width: 900px) {
  .juba-duo-mobile-bar {
    padding-top:env(safe-area-inset-top, 0px);
  }
  .juba-duo-home,
  .juba-duo-shell[dir="rtl"] .juba-duo-home {
    padding-top:calc(78px + env(safe-area-inset-top, 0px));
  }
  .juba-duo-main {
    margin-inline-start:0;
    margin-inline-end:0;
  }
  .juba-duo-sidebar { display:none; }
  .juba-duo-home,
  .juba-duo-shell[dir="rtl"] .juba-duo-home { width:100%; margin:0; padding:78px 18px 40px; }
  .juba-duo-welcome { align-items:stretch; flex-direction:column; }
  .juba-duo-top-stats { width:100%; }
  .juba-duo-top-stats > div { flex:1; }
  .juba-duo-grid { grid-template-columns:1fr; }
  .juba-duo-side { display:grid; grid-template-columns:1fr 1fr; gap:12px; }
  .juba-duo-side .juba-duo-card { margin:0; }
  .juba-duo-side .juba-duo-links { grid-column:1/-1; }
}
@media (min-width: 901px) {
  .juba-duo-mobile-bar { display:none !important; }
  .juba-duo-mobile-menu { display:none !important; }
}
@media (max-width: 560px) {
  .juba-duo-node-row.is-offset,
  .juba-duo-shell[dir="rtl"] .juba-duo-node-row.is-offset { transform:none; }
}
@media (max-width: 420px) {
  .juba-duo-top-stats { flex-direction:column; }
  .juba-duo-top-stats > div { min-width:0; width:100%; }
  .juba-duo-node-row { gap:12px; }
  .juba-duo-node-copy { min-width:0; }
  .juba-duo-node-copy strong,
  .juba-duo-node-copy span { overflow-wrap:anywhere; }
}

@media (max-width: 560px) {
  .juba-duo-home,
  .juba-duo-shell[dir="rtl"] .juba-duo-home { padding-inline:12px; }
  .juba-duo-unit { padding:15px; }
  .juba-duo-unit-head { align-items:flex-start; flex-direction:column; }
  .juba-duo-node-row.is-offset { transform:none; }
  .juba-duo-node { width:58px; height:58px; flex-basis:58px; }
  .juba-duo-node-copy strong { font-size:13px; }
  .juba-duo-side { grid-template-columns:1fr; }
  .juba-duo-premium { align-items:flex-start; flex-wrap:wrap; }
}

/* Internal routes that still use the legacy semantic utility tokens inherit
   the Duolingo application palette without changing their business logic. */
.juba-duo-shell .text-fl-label,
.juba-duo-shell .text-fl-caption,
.juba-duo-shell .text-fl-hint { color:var(--duo-muted) !important; }

/* ── Duolingo application content frame ────────────────────────────────────
   Shared chrome for every authenticated route. Feature-specific components
   keep their own layout and behavior; this block only supplies the common
   application surface, typography, controls, cards and RTL geometry.
   ------------------------------------------------------------------------- */
.juba-duo-main {
  flex:1;
  min-width:0;
  min-height:100dvh;
  height:100dvh;
  display:flex;
  flex-direction:column;
  overflow:hidden;
  background:var(--duo-bg);
  margin-inline-start:250px;
}
.juba-duo-shell[dir="rtl"] .juba-duo-main {
  margin-inline-start:0;
  margin-inline-end:250px;
}
.juba-duo-page-frame {
  min-width:0;
  min-height:0;
  width:100%;
  margin:0;
  flex:1;
  overflow-y:auto;
  overflow-x:hidden;
  background:var(--duo-bg);
}

/* Shared page rhythm */
.juba-duo-page-frame > div:not(.juba-duo-home),
.juba-duo-page-frame > section:not(.juba-duo-home) {
  color:var(--duo-ink);
}
.juba-duo-page-frame h1,
.juba-duo-page-frame h2,
.juba-duo-page-frame h3,
.juba-duo-page-frame h4 {
  color:var(--duo-ink);
  letter-spacing:-.025em;
}
.juba-duo-page-frame a {
  color:var(--duo-blue-dark);
}
.juba-duo-page-frame a:hover {
  color:var(--duo-blue-dark);
}

/* Existing semantic cards become Duolingo-style surfaces without requiring
   every route to be rewritten around the new design system. */
.juba-duo-page-frame .bg-fl-surface,
.juba-duo-page-frame .bg-fl-surface-2 {
  background:var(--duo-card) !important;
}
.juba-duo-page-frame .border-fl-border,
.juba-duo-page-frame .border-fl-border-2 {
  border-color:var(--duo-line) !important;
}
.juba-duo-page-frame .rounded-lg,
.juba-duo-page-frame .rounded-xl {
  border-radius:14px;
}
.juba-duo-page-frame button:not(.juba-duo-user-action):not(.juba-duo-mobile-trigger) {
  min-height:40px;
  font-weight:750;
}
.juba-duo-page-frame input:focus,
.juba-duo-page-frame select:focus,
.juba-duo-page-frame textarea:focus,
.juba-duo-page-frame button:focus-visible,
.juba-duo-page-frame a:focus-visible {
  outline:3px solid color-mix(in srgb,var(--duo-blue) 22%,transparent);
  outline-offset:2px;
}
.juba-duo-page-frame input,
.juba-duo-page-frame select,
.juba-duo-page-frame textarea {
