.juba-busuu-dashboard .juba-duo-path:after{
  content:"";
  position:absolute;
  inset-inline-start:29px;
  inset-block-start:34px;
  width:16px;
  height:16px;
  border-radius:50%;
  background:#58a700;
  box-shadow:0 0 0 5px #eef7e8;
  opacity:.9;
  pointer-events:none;
