  --ref-green-dark:#46a302;
  --ref-ink:#4b4b4b;
  --ref-muted:#8a8a8a;
  --ref-line:#e7e7e7;
  --ref-bg:#f7f7f7;
  background:var(--ref-bg)!important;
}
.juba-reference-v3 .juba-reference-v3-grid{
  width:min(1180px,100%)!important;
  max-width:1180px!important;
  grid-template-columns:minmax(0,1fr) 300px!important;
  gap:24px!important;
  padding:22px 28px 48px!important;
}
.juba-reference-v3 .juba-reference-v3-main{
  display:flex!important;
  flex-direction:column!important;
  gap:16px!important;
  min-width:0!important;
}
.juba-reference-v3 .juba-reference-v3-main>.juba-reference-v3-welcome{order:1}
.juba-reference-v3 .juba-reference-v3-main>.juba-reference-course{order:2}
.juba-reference-v3 .juba-reference-v3-main>.juba-reference-daily{order:3}
.juba-reference-v3 .juba-reference-v3-main>.juba-reference-reference-insights{order:4}
.juba-reference-v3 .juba-reference-v3-main>.juba-reference-achievement-strip{order:5}

.juba-reference-v3 .juba-reference-v3-card,
.juba-reference-v3 .juba-reference-v3-welcome{
  border:1px solid var(--ref-line)!important;
  border-radius:9px!important;
  box-shadow:0 1px 2px rgba(0,0,0,.025)!important;
  background:#fff!important;
}
.juba-reference-v3 .juba-reference-v3-card-head{
  min-height:42px!important;
  padding-bottom:11px!important;
  border-bottom:1px solid #eeeeee!important;
}
.juba-reference-v3 .juba-reference-section-label{
  color:#a0a0a0!important;
  font-size:8px!important;
  line-height:1!important;
  letter-spacing:.08em!important;
  text-transform:uppercase!important;
  font-weight:900!important;
}
.juba-reference-v3 .juba-reference-v3-card-head h2,
.juba-reference-v3 .juba-reference-v3-card-head h3{
  color:var(--ref-ink)!important;
  font-weight:900!important;
  letter-spacing:-.015em!important;
}
.juba-reference-v3 .juba-reference-v3-welcome{
  min-height:112px!important;
  padding:20px 22px!important;
  border-radius:9px!important;
}
.juba-reference-v3 .juba-reference-v3-welcome h2{
  font-size:19px!important;
  color:#3f3f3f!important;
}
.juba-reference-v3 .juba-reference-v3-welcome p{
  max-width:620px!important;
  color:#8b8b8b!important;
  font-size:10px!important;
  line-height:1.45!important;
}
.juba-reference-v3 .juba-reference-v3-level{
  width:74px!important;
  height:74px!important;
  flex-basis:74px!important;
  border-width:5px!important;
  box-shadow:0 1px 2px rgba(0,0,0,.03)!important;
}
.juba-reference-v3 .juba-reference-v3-level span{
  font-size:13px!important;
  font-weight:950!important;
}
.juba-reference-v3 .juba-reference-v3-level small{
  font-size:8px!important;
  font-weight:900!important;
}
.juba-reference-v3 .juba-reference-course{
  overflow:hidden!important;
}
.juba-reference-v3 .juba-reference-course>.juba-reference-v3-card-head{
  padding:15px 18px 12px!important;
}
.juba-reference-v3 .juba-reference-course-path{
  border:0!important;
  border-radius:0!important;
}
.juba-reference-v3 .juba-reference-course-path::before,
.juba-reference-v3 .juba-reference-course-path::after{
  inset-inline-start:35px!important;
}
.juba-reference-v3 .juba-reference-course-path .juba-reference-lesson{
  min-height:68px!important;
  grid-template-columns:40px minmax(0,1fr) auto!important;
  padding:10px 18px!important;
}
.juba-reference-v3 .juba-reference-path-node{
  width:32px!important;
  height:32px!important;
  border-width:2px!important;
}
.juba-reference-v3 .juba-reference-lesson-copy strong{
  color:#555!important;
  font-size:11px!important;
  font-weight:900!important;
}
.juba-reference-v3 .juba-reference-lesson-copy span{
  color:#a0a0a0!important;
  font-size:8px!important;
}
.juba-reference-v3 .juba-reference-lesson.current .juba-reference-lesson-copy strong{
  color:#58a91b!important;
}
.juba-reference-v3 .juba-reference-green-button{
  min-height:30px!important;
  padding:0 13px!important;
  border-radius:7px!important;
  background:var(--ref-green)!important;
