}
.juba-reference-v3 .juba-reference-v3-chart-col.active span{
  background:var(--ref-green)!important;
}
.juba-reference-v3 .juba-reference-chart-summary{
  margin-top:11px!important;
  padding-top:11px!important;
  border-top:1px solid #eeeeee!important;
}
.juba-reference-v3 .juba-reference-reference-insights{
  display:grid!important;
  grid-template-columns:1fr 1fr!important;
  gap:16px!important;
}
.juba-reference-v3 .juba-reference-insight-card{
  min-height:142px!important;
  padding:16px 18px!important;
}
.juba-reference-v3 .juba-reference-insight-value strong,
.juba-reference-v3 .juba-reference-words-value strong{
  color:#4b4b4b!important;
  font-size:25px!important;
  font-weight:950!important;
}
.juba-reference-v3 .juba-reference-insight-track{
  height:7px!important;
  margin:13px 0 10px!important;
  border-radius:99px!important;
  background:#edf0ed!important;
}
.juba-reference-v3 .juba-reference-insight-track span{
  border-radius:99px!important;
  background:var(--ref-green)!important;
}
.juba-reference-v3 .juba-reference-v3-rail{
  display:flex!important;
  flex-direction:column!important;
  gap:14px!important;
}
.juba-reference-v3 .juba-reference-v3-rail>.juba-reference-v3-card{
  padding:16px!important;
}
.juba-reference-v3 .juba-reference-profile-card{
  min-height:118px!important;
}
.juba-reference-v3 .juba-reference-goal-card{
  min-height:154px!important;
}
.juba-reference-v3 .juba-reference-xp-card{
  min-height:150px!important;
}
.juba-reference-v3 .juba-reference-achievement-card{
  min-height:128px!important;
}
.juba-reference-v3 .juba-reference-tools-card{
  min-height:100px!important;
}
@media (max-width:1200px){
  .juba-reference-v3 .juba-reference-v3-grid{
    grid-template-columns:minmax(0,1fr) 278px!important;
    padding-inline:20px!important;
  }
}
@media (max-width:900px){
  .juba-reference-v3 .juba-reference-v3-grid{
    grid-template-columns:1fr!important;
  }
  .juba-reference-v3 .juba-reference-v3-rail{
    display:grid!important;
    grid-template-columns:repeat(2,minmax(0,1fr))!important;
  }
}
@media (max-width:640px){
  .juba-reference-v3 .juba-reference-v3-grid{
    padding:14px 12px 30px!important;
  }
  .juba-reference-v3 .juba-reference-reference-insights,
  .juba-reference-v3 .juba-reference-v3-rail{
    grid-template-columns:1fr!important;
  }
  .juba-reference-v3 .juba-reference-v3-welcome{
    min-height:100px!important;
    padding:16px!important;
  }
  .juba-reference-v3 .juba-reference-v3-level{
    width:62px!important;
    height:62px!important;
